-- Onda 3.2 ressalva do #1363 (revisor 24/11/2026; dono, chat, 24/11/2026: marcos de lei sem linha propria vao para MARCO_LEGAL).
-- So dado, sem DDL (a coluna `tabela` e texto livre). Tres linhas: INICIO_OPCAO_IBS_CBS_DAS (LC 214 art. 517 + 544 III),
-- FIM_REGIME_CAIXA_SIMPLES (Res. CGSN 190/2026 art. 9o II, red. Res. CGSN 196/2026) e INICIO_IBS_MUNICIPAL (LC 214 arts. 343-344).
-- Se abortar: o SQLite nao e transacional no migrate deploy, mas sao INSERT OR IGNORE com id fixo, sem assercao nem tabela-sonda;
-- retomar e reaplicar (a linha ja gravada e ignorada).
-- Os INSERTs sao o texto de prisma/data/legal_parameters_marco_legal_v2.sql (teste-guarda de igualdade).
INSERT OR IGNORE INTO "legal_parameters" ("id","tabela","chave","discriminador","valorInt","valorTexto","valorJson","fonte","fonteUrl","fonteSha256","vigenteDesde","vigenteAte","status","supersedesId","motivo","proposedById","publishedById","publishedAt","createdAt") VALUES ('lp-marco-ibscbs-opcao-das', 'MARCO_LEGAL', 'INICIO_OPCAO_IBS_CBS_DAS', NULL, NULL, '2027-01-01', NULL, 'LC 214/2025 art. 517 (nova redação do art. 13 da LC 123/2006, IX–X e §§ 9º a 11: o optante pelo Simples Nacional pode apurar e recolher IBS e CBS pelo regime regular, por semestre; red. LC 227/2026), com efeitos a partir de 01/01/2027 pelo art. 544 III', 'https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp214.htm', 'f352e0adf358fbdcf82a10b57b7ddb22d3be19197d816605402e617e8bddfe90', '2025-01-16', NULL, 'PUBLISHED', NULL, 'Onda 3.2 ressalva #1363 (dono, chat, 24/11/2026: tabela MARCO_LEGAL); texto lido no Planalto em 24/11/2026 (dossiê marcos-restantes-onda32; marco-legal-lc214 [D02]); substitui o literal 2027 de CompanyFiscalProfileService (trava do upsert e ibsCbsNoDas)', 'migracao:ONDA3-2-F4', 'migracao:ONDA3-2-F4', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO "legal_parameters" ("id","tabela","chave","discriminador","valorInt","valorTexto","valorJson","fonte","fonteUrl","fonteSha256","vigenteDesde","vigenteAte","status","supersedesId","motivo","proposedById","publishedById","publishedAt","createdAt") VALUES ('lp-marco-simples-fim-caixa', 'MARCO_LEGAL', 'FIM_REGIME_CAIXA_SIMPLES', NULL, NULL, '2027-01-01', NULL, 'Res. CGSN 190/2026 art. 1º (nova redação do art. 16 caput da Res. CGSN 140/2018: base de cálculo = receita bruta total mensal auferida) e art. 8º IX e XII (revogam o art. 16 § 1º e os arts. 19 e 20), com efeitos a partir de 01/01/2027 pelo art. 9º II (red. Res. CGSN 196/2026, vigência 24/11/2026)', 'https://normas.receita.fazenda.gov.br/sijut2consulta/link.action?idAto=152832', '38a118e86ac90bd8f9bd9f4efb8e2fe947cc5af9216c27150d3a5537ca68e66f', '2026-08-10', NULL, 'PUBLISHED', NULL, 'Onda 3.2 ressalva #1363 (dono, chat, 24/11/2026: tabela MARCO_LEGAL); visão multivigente lida no Normas RFB em 24/11/2026 (dossiê marcos-restantes-onda32 [D02]; a Res. 196 mudou o art. 9º, que antes tinha um só efeito); a fonte NÃO está no acervo ctresb/leis; substitui o literal 2027 de assertCaixaAte2026', 'migracao:ONDA3-2-F4', 'migracao:ONDA3-2-F4', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO "legal_parameters" ("id","tabela","chave","discriminador","valorInt","valorTexto","valorJson","fonte","fonteUrl","fonteSha256","vigenteDesde","vigenteAte","status","supersedesId","motivo","proposedById","publishedById","publishedAt","createdAt") VALUES ('lp-marco-ibs-municipal', 'MARCO_LEGAL', 'INICIO_IBS_MUNICIPAL', NULL, NULL, '2027-01-01', NULL, 'LC 214/2025 art. 343 (fatos geradores de 01/01 a 31/12/2026: IBS só à alíquota estadual de 0,1%) e art. 344 (a partir de 01/01/2027: alíquota estadual de 0,05% e alíquota municipal de 0,05%)', 'https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp214.htm', 'f352e0adf358fbdcf82a10b57b7ddb22d3be19197d816605402e617e8bddfe90', '2025-01-16', NULL, 'PUBLISHED', NULL, 'Onda 3.2 ressalva #1363 (dono, chat, 24/11/2026: tabela MARCO_LEGAL); texto lido no Planalto em 24/11/2026 (dossiê marco-legal-lc214 [D02]); substitui o literal 2027-01-01 de aliquotasIbsCbsVigentes (IBS municipal zero antes do marco)', 'migracao:ONDA3-2-F4', 'migracao:ONDA3-2-F4', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
